def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    # If there was a mutual defection in the last 3 rounds, cooperate to repair.
    start = max(0, n - 3)
    for i in range(start, n):
        if history[i][0] == 'D' and history[i][1] == 'D':
            return 'C'
    # Otherwise, use Pavlov: punish defection, reward cooperation, exploit unconditional cooperators.
    last = history[-1]
    if (last[0] == 'C' and last[1] == 'D') or (last[0] == 'D' and last[1] == 'C'):
        return 'D'
    return 'C'
